module axixclk #(
		parameter integer C_S_AXI_ID_WIDTH	= 2,
		parameter integer C_S_AXI_DATA_WIDTH	= 32,
		parameter integer C_S_AXI_ADDR_WIDTH	= 6,
		parameter [0:0]	OPT_WRITE_ONLY = 1'b0,
		parameter [0:0]	OPT_READ_ONLY = 1'b0,
		parameter	XCLOCK_FFS = 2,
		parameter	LGFIFO = 5
	) (
		input	wire				S_AXI_ACLK,
		input	wire				S_AXI_ARESETN,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_AWID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_AWADDR,
		input	wire [7 : 0]			S_AXI_AWLEN,
		input	wire [2 : 0]			S_AXI_AWSIZE,
		input	wire [1 : 0]			S_AXI_AWBURST,
		input	wire				S_AXI_AWLOCK,
		input	wire [3 : 0]			S_AXI_AWCACHE,
		input	wire [2 : 0]			S_AXI_AWPROT,
		input	wire [3 : 0]			S_AXI_AWQOS,
		input	wire				S_AXI_AWVALID,
		output	wire				S_AXI_AWREADY,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_WDATA,
		input	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] S_AXI_WSTRB,
		input	wire				S_AXI_WLAST,
		input	wire				S_AXI_WVALID,
		output	wire				S_AXI_WREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_BID,
		output	wire [1 : 0]			S_AXI_BRESP,
		output	wire				S_AXI_BVALID,
		input	wire				S_AXI_BREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_ARID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_ARADDR,
		input	wire [7 : 0]			S_AXI_ARLEN,
		input	wire [2 : 0]			S_AXI_ARSIZE,
		input	wire [1 : 0]			S_AXI_ARBURST,
		input	wire				S_AXI_ARLOCK,
		input	wire [3 : 0]			S_AXI_ARCACHE,
		input	wire [2 : 0]			S_AXI_ARPROT,
		input	wire [3 : 0]			S_AXI_ARQOS,
		input	wire				S_AXI_ARVALID,
		output	wire				S_AXI_ARREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_RID,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_RDATA,
		output	wire [1 : 0]			S_AXI_RRESP,
		output	wire				S_AXI_RLAST,
		output	wire				S_AXI_RVALID,
		input	wire				S_AXI_RREADY,
		input	wire				M_AXI_ACLK,
		output	wire				M_AXI_ARESETN,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_AWID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_AWADDR,
		output	wire [7 : 0]			M_AXI_AWLEN,
		output	wire [2 : 0]			M_AXI_AWSIZE,
		output	wire [1 : 0]			M_AXI_AWBURST,
		output	wire				M_AXI_AWLOCK,
		output	wire [3 : 0]			M_AXI_AWCACHE,
		output	wire [2 : 0]			M_AXI_AWPROT,
		output	wire [3 : 0]			M_AXI_AWQOS,
		output	wire				M_AXI_AWVALID,
		input	wire				M_AXI_AWREADY,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_WDATA,
		output	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] M_AXI_WSTRB,
		output	wire				M_AXI_WLAST,
		output	wire				M_AXI_WVALID,
		input	wire				M_AXI_WREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_BID,
		input	wire [1 : 0]			M_AXI_BRESP,
		input	wire				M_AXI_BVALID,
		output	wire				M_AXI_BREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_ARID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_ARADDR,
		output	wire [7 : 0]			M_AXI_ARLEN,
		output	wire [2 : 0]			M_AXI_ARSIZE,
		output	wire [1 : 0]			M_AXI_ARBURST,
		output	wire				M_AXI_ARLOCK,
		output	wire [3 : 0]			M_AXI_ARCACHE,
		output	wire [2 : 0]			M_AXI_ARPROT,
		output	wire [3 : 0]			M_AXI_ARQOS,
		output	wire				M_AXI_ARVALID,
		input	wire				M_AXI_ARREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_RID,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_RDATA,
		input	wire [1 : 0]			M_AXI_RRESP,
		input	wire				M_AXI_RLAST,
		input	wire				M_AXI_RVALID,
		output	wire				M_AXI_RREADY
	);

	// Local parameters
	localparam integer FIFO_DEPTH = 1 << LGFIFO;
	localparam integer FIFO_ADDR_WIDTH = LGFIFO;
	localparam integer FFS_STAGES = XCLOCK_FFS;

	// Internal signals
	wire [C_S_AXI_ID_WIDTH-1 : 0] s_awid;
	wire [C_S_AXI_ADDR_WIDTH-1 : 0] s_awaddr;
	wire [7 : 0] s_awlen;
	wire [2 : 0] s_awsize;
	wire [1 : 0] s_awburst;
	wire s_awlock;
	wire [3 : 0] s_awcache;
	wire [2 : 0] s_awprot;
	wire [3 : 0] s_awqos;
	wire s_awvalid;
	wire s_awready;

	wire [C_S_AXI_DATA_WIDTH-1 : 0] s_wdata;
	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] s_wstrb;
	wire s_wlast;
	wire s_wvalid;
	wire s_wready;

	wire [C_S_AXI_ID_WIDTH-1 : 0] s_bid;
	wire [1 : 0] s_bresp;
	wire s_bvalid;
	wire s_bready;

	wire [C_S_AXI_ID_WIDTH-1 : 0] s_arid;
	wire [C_S_AXI_ADDR_WIDTH-1 : 0] s_araddr;
	wire [7 : 0] s_arlen;
	wire [2 : 0] s_arsize;
	wire [1 : 0] s_arburst;
	wire s_arlock;
	wire [3 : 0] s_arcache;
	wire [2 : 0] s_arprot;
	wire [3 : 0] s_arqos;
	wire s_arvalid;
	wire s_arready;

	wire [C_S_AXI_ID_WIDTH-1 : 0] s_rid;
	wire [C_S_AXI_DATA_WIDTH-1 : 0] s_rdata;
	wire [1 : 0] s_rresp;
	wire s_rlast;
	wire s_rvalid;
	wire s_rready;

	wire m_awid;
	wire [C_S_AXI_ADDR_WIDTH-1 : 0] m_awaddr;
	wire [7 : 0] m_awlen;
	wire [2 : 0] m_awsize;
	wire [1 : 0] m_awburst;
	wire m_awlock;
	wire [3 : 0] m_awcache;
	wire [2 : 0] m_awprot;
	wire [3 : 0] m_awqos;
	wire m_awvalid;
	wire m_awready;

	wire [C_S_AXI_DATA_WIDTH-1 : 0] m_wdata;
	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] m_wstrb;
	wire m_wlast;
	wire m_wvalid;
	wire m_wready;

	wire [C_S_AXI_ID_WIDTH-1 : 0] m_bid;
	wire [1 : 0] m_bresp;
	wire m_bvalid;
	wire m_bready;

	wire [C_S_AXI_ID_WIDTH-1 : 0] m_arid;
	wire [C_S_AXI_ADDR_WIDTH-1 : 0] m_araddr;
	wire [7 : 0] m_arlen;
	wire [2 : 0] m_arsize;
	wire [1 : 0] m_arburst;
	wire m_arlock;
	wire [3 : 0] m_arcache;
	wire [2 : 0] m_arprot;
	wire [3 : 0] m_arqos;
	wire m_arvalid;
	wire m_arready;

	wire [C_S_AXI_ID_WIDTH-1 : 0] m_rid;
	wire [C_S_AXI_DATA_WIDTH-1 : 0] m_rdata;
	wire [1 : 0] m_rresp;
	wire m_rlast;
	wire m_rvalid;
	wire m_rready;

	// Reset synchronization
	reg [FFS_STAGES-1 : 0] m_reset_sync;
	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			m_reset_sync <= {FFS_STAGES{1'b0}};
		else
			m_reset_sync <= {m_reset_sync[FFS_STAGES-2 : 0], 1'b1};
	end
	assign M_AXI_ARESETN = m_reset_sync[FFS_STAGES-1];

	// AW Channel: S to M
	// FIFO for AW channel
	reg [C_S_AXI_ID_WIDTH-1 : 0] aw_fifo_data [0 : FIFO_DEPTH-1];
	reg [C_S_AXI_ADDR_WIDTH-1 : 0] aw_fifo_addr [0 : FIFO_DEPTH-1];
	reg [7 : 0] aw_fifo_len [0 : FIFO_DEPTH-1];
	reg [2 : 0] aw_fifo_size [0 : FIFO_DEPTH-1];
	reg [1 : 0] aw_fifo_burst [0 : FIFO_DEPTH-1];
	reg aw_fifo_lock [0 : FIFO_DEPTH-1];
	reg [3 : 0] aw_fifo_cache [0 : FIFO_DEPTH-1];
	reg [2 : 0] aw_fifo_prot [0 : FIFO_DEPTH-1];
	reg [3 : 0] aw_fifo_qos [0 : FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH-1 : 0] aw_fifo_wr_ptr, aw_fifo_rd_ptr;
	reg aw_fifo_full, aw_fifo_empty;

	// AW FIFO write logic (S clock)
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			aw_fifo_wr_ptr <= {FIFO_ADDR_WIDTH{1'b0}};
			aw_fifo_full <= 1'b0;
		end else begin
			if (s_awvalid && s_awready) begin
				aw_fifo_data[aw_fifo_wr_ptr] <= S_AXI_AWID;
				aw_fifo_addr[aw_fifo_wr_ptr] <= S_AXI_AWADDR;
				aw_fifo_len[aw_fifo_wr_ptr] <= S_AXI_AWLEN;
				aw_fifo_size[aw_fifo_wr_ptr] <= S_AXI_AWSIZE;
				aw_fifo_burst[aw_fifo_wr_ptr] <= S_AXI_AWBURST;
				aw_fifo_lock[aw_fifo_wr_ptr] <= S_AXI_AWLOCK;
				aw_fifo_cache[aw_fifo_wr_ptr] <= S_AXI_AWCACHE;
				aw_fifo_prot[aw_fifo_wr_ptr] <= S_AXI_AWPROT;
				aw_fifo_qos[aw_fifo_wr_ptr] <= S_AXI_AWQOS;
				aw_fifo_wr_ptr <= aw_fifo_wr_ptr + 1'b1;
			end
		end
	end

	// AW FIFO read logic (M clock)
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			aw_fifo_rd_ptr <= {FIFO_ADDR_WIDTH{1'b0}};
			aw_fifo_empty <= 1'b1;
		end else begin
			if (m_awvalid && m_awready) begin
				aw_fifo_rd_ptr <= aw_fifo_rd_ptr + 1'b1;
			end
		end
	end

	// AW FIFO status
	always @(*) begin
		if (aw_fifo_wr_ptr == aw_fifo_rd_ptr) begin
			aw_fifo_full = 1'b0;
			aw_fifo_empty = 1'b1;
		end else if (aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] != aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1]) begin
			aw_fifo_full = aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] > aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1];
			aw_fifo_empty = 1'b0;
		end else begin
			aw_fifo_full = aw_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] < aw_fifo_rd_ptr[FIFO_ADDR_WIDTH-1];
			aw_fifo_empty = 1'b0;
		end
	end

	// AW channel outputs
	assign s_awready = !aw_fifo_full;
	assign s_awvalid = S_AXI_AWVALID;
	assign s_awid = S_AXI_AWID;
	assign s_awaddr = S_AXI_AWADDR;
	assign s_awlen = S_AXI_AWLEN;
	assign s_awsize = S_AXI_AWSIZE;
	assign s_awburst = S_AXI_AWBURST;
	assign s_awlock = S_AXI_AWLOCK;
	assign s_awcache = S_AXI_AWCACHE;
	assign s_awprot = S_AXI_AWPROT;
	assign s_awqos = S_AXI_AWQOS;

	assign m_awid = aw_fifo_data[aw_fifo_rd_ptr];
	assign m_awaddr = aw_fifo_addr[aw_fifo_rd_ptr];
	assign m_awlen = aw_fifo_len[aw_fifo_rd_ptr];
	assign m_awsize = aw_fifo_size[aw_fifo_rd_ptr];
	assign m_awburst = aw_fifo_burst[aw_fifo_rd_ptr];
	assign m_awlock = aw_fifo_lock[aw_fifo_rd_ptr];
	assign m_awcache = aw_fifo_cache[aw_fifo_rd_ptr];
	assign m_awprot = aw_fifo_prot[aw_fifo_rd_ptr];
	assign m_awqos = aw_fifo_qos[aw_fifo_rd_ptr];
	assign m_awvalid = !aw_fifo_empty;
	assign m_awready = M_AXI_AWREADY;

	// W Channel: S to M
	// FIFO for W channel
	reg [C_S_AXI_DATA_WIDTH-1 : 0] w_fifo_data [0 : FIFO_DEPTH-1];
	reg [(C_S_AXI_DATA_WIDTH/8)-1 : 0] w_fifo_strb [0 : FIFO_DEPTH-1];
	reg w_fifo_last [0 : FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH-1 : 0] w_fifo_wr_ptr, w_fifo_rd_ptr;
	reg w_fifo_full, w_fifo_empty;

	// W FIFO write logic (S clock)
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			w_fifo_wr_ptr <= {FIFO_ADDR_WIDTH{1'b0}};
			w_fifo_full <= 1'b0;
		end else begin
			if (s_wvalid && s_wready) begin
				w_fifo_data[w_fifo_wr_ptr] <= S_AXI_WDATA;
				w_fifo_strb[w_fifo_wr_ptr] <= S_AXI_WSTRB;
				w_fifo_last[w_fifo_wr_ptr] <= S_AXI_WLAST;
				w_fifo_wr_ptr <= w_fifo_wr_ptr + 1'b1;
			end
		end
	end

	// W FIFO read logic (M clock)
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			w_fifo_rd_ptr <= {FIFO_ADDR_WIDTH{1'b0}};
			w_fifo_empty <= 1'b1;
		end else begin
			if (m_wvalid && m_wready) begin
				w_fifo_rd_ptr <= w_fifo_rd_ptr + 1'b1;
			end
		end
	end

	// W FIFO status
	always @(*) begin
		if (w_fifo_wr_ptr == w_fifo_rd_ptr) begin
			w_fifo_full = 1'b0;
			w_fifo_empty = 1'b1;
		end else if (w_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] != w_fifo_rd_ptr[FIFO_ADDR_WIDTH-1]) begin
			w_fifo_full = w_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] > w_fifo_rd_ptr[FIFO_ADDR_WIDTH-1];
			w_fifo_empty = 1'b0;
		end else begin
			w_fifo_full = w_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] < w_fifo_rd_ptr[FIFO_ADDR_WIDTH-1];
			w_fifo_empty = 1'b0;
		end
	end

	// W channel outputs
	assign s_wready = !w_fifo_full;
	assign s_wvalid = S_AXI_WVALID;
	assign s_wdata = S_AXI_WDATA;
	assign s_wstrb = S_AXI_WSTRB;
	assign s_wlast = S_AXI_WLAST;

	// M_WVALID is held one extra M_AXI clock before M_AXI_WVALID
	reg m_wvalid_reg;
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN)
			m_wvalid_reg <= 1'b0;
		else
			m_wvalid_reg <= !w_fifo_empty;
	end

	assign m_wdata = w_fifo_data[w_fifo_rd_ptr];
	assign m_wstrb = w_fifo_strb[w_fifo_rd_ptr];
	assign m_wlast = w_fifo_last[w_fifo_rd_ptr];
	assign m_wvalid = m_wvalid_reg;
	assign m_wready = M_AXI_WREADY;

	// B Channel: M to S
	// FIFO for B channel
	reg [C_S_AXI_ID_WIDTH-1 : 0] b_fifo_id [0 : FIFO_DEPTH-1];
	reg [1 : 0] b_fifo_resp [0 : FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH-1 : 0] b_fifo_wr_ptr, b_fifo_rd_ptr;
	reg b_fifo_full, b_fifo_empty;

	// B FIFO write logic (M clock)
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			b_fifo_wr_ptr <= {FIFO_ADDR_WIDTH{1'b0}};
			b_fifo_full <= 1'b0;
		end else begin
			if (m_bvalid && m_bready) begin
				b_fifo_id[b_fifo_wr_ptr] <= M_AXI_BID;
				b_fifo_resp[b_fifo_wr_ptr] <= M_AXI_BRESP;
				b_fifo_wr_ptr <= b_fifo_wr_ptr + 1'b1;
			end
		end
	end

	// B FIFO read logic (S clock)
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			b_fifo_rd_ptr <= {FIFO_ADDR_WIDTH{1'b0}};
			b_fifo_empty <= 1'b1;
		end else begin
			if (s_bvalid && s_bready) begin
				b_fifo_rd_ptr <= b_fifo_rd_ptr + 1'b1;
			end
		end
	end

	// B FIFO status
	always @(*) begin
		if (b_fifo_wr_ptr == b_fifo_rd_ptr) begin
			b_fifo_full = 1'b0;
			b_fifo_empty = 1'b1;
		end else if (b_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] != b_fifo_rd_ptr[FIFO_ADDR_WIDTH-1]) begin
			b_fifo_full = b_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] > b_fifo_rd_ptr[FIFO_ADDR_WIDTH-1];
			b_fifo_empty = 1'b0;
		end else begin
			b_fifo_full = b_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] < b_fifo_rd_ptr[FIFO_ADDR_WIDTH-1];
			b_fifo_empty = 1'b0;
		end
	end

	// B channel outputs
	assign m_bready = !b_fifo_full;
	assign m_bvalid = M_AXI_BVALID;
	assign m_bid = M_AXI_BID;
	assign m_bresp = M_AXI_BRESP;

	assign s_bid = b_fifo_id[b_fifo_rd_ptr];
	assign s_bresp = b_fifo_resp[b_fifo_rd_ptr];
	assign s_bvalid = !b_fifo_empty;
	assign s_bready = S_AXI_BREADY;

	// AR Channel: S to M
	// FIFO for AR channel
	reg [C_S_AXI_ID_WIDTH-1 : 0] ar_fifo_id [0 : FIFO_DEPTH-1];
	reg [C_S_AXI_ADDR_WIDTH-1 : 0] ar_fifo_addr [0 : FIFO_DEPTH-1];
	reg [7 : 0] ar_fifo_len [0 : FIFO_DEPTH-1];
	reg [2 : 0] ar_fifo_size [0 : FIFO_DEPTH-1];
	reg [1 : 0] ar_fifo_burst [0 : FIFO_DEPTH-1];
	reg ar_fifo_lock [0 : FIFO_DEPTH-1];
	reg [3 : 0] ar_fifo_cache [0 : FIFO_DEPTH-1];
	reg [2 : 0] ar_fifo_prot [0 : FIFO_DEPTH-1];
	reg [3 : 0] ar_fifo_qos [0 : FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH-1 : 0] ar_fifo_wr_ptr, ar_fifo_rd_ptr;
	reg ar_fifo_full, ar_fifo_empty;

	// AR FIFO write logic (S clock)
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			ar_fifo_wr_ptr <= {FIFO_ADDR_WIDTH{1'b0}};
			ar_fifo_full <= 1'b0;
		end else begin
			if (s_arvalid && s_arready) begin
				ar_fifo_id[ar_fifo_wr_ptr] <= S_AXI_ARID;
				ar_fifo_addr[ar_fifo_wr_ptr] <= S_AXI_ARADDR;
				ar_fifo_len[ar_fifo_wr_ptr] <= S_AXI_ARLEN;
				ar_fifo_size[ar_fifo_wr_ptr] <= S_AXI_ARSIZE;
				ar_fifo_burst[ar_fifo_wr_ptr] <= S_AXI_ARBURST;
				ar_fifo_lock[ar_fifo_wr_ptr] <= S_AXI_ARLOCK;
				ar_fifo_cache[ar_fifo_wr_ptr] <= S_AXI_ARCACHE;
				ar_fifo_prot[ar_fifo_wr_ptr] <= S_AXI_ARPROT;
				ar_fifo_qos[ar_fifo_wr_ptr] <= S_AXI_ARQOS;
				ar_fifo_wr_ptr <= ar_fifo_wr_ptr + 1'b1;
			end
		end
	end

	// AR FIFO read logic (M clock)
	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			ar_fifo_rd_ptr <= {FIFO_ADDR_WIDTH{1'b0}};
			ar_fifo_empty <= 1'b1;
		end else begin
			if (m_arvalid && m_arready) begin
				ar_fifo_rd_ptr <= ar_fifo_rd_ptr + 1'b1;
			end
		end
	end

	// AR FIFO status
	always @(*) begin
		if (ar_fifo_wr_ptr == ar_fifo_rd_ptr) begin
			ar_fifo_full = 1'b0;
			ar_fifo_empty = 1'b1;
		end else if (ar_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] != ar_fifo_rd_ptr[FIFO_ADDR_WIDTH-1]) begin
			ar_fifo_full = ar_fifo_wr_ptr[FIFO_ADDR_WIDTH-1] > ar_fifo_rd_ptr[FIFO_ADDR_WIDTH-1];
			ar_fifo_empty = 1'b0;
		end else begin
